class VNCAuthenticator(StatefulProtocol):
    VERSION = "RFB 003.008\n"
    def __init__(self, password):
        self.password = password
        self.authentication_d = Deferred()
    def authenticated(self):
        """
        Switch to proxy mode.
        """
