class VNCProxy(Factory):
    def __init__(self, host, port, password, client_opts):
        self.host = host
        self.port = port
        self.password = password
        self.client_opts = client_opts
    def buildProtocol(self, a):
        server = self.protocol(self.password, self.client_opts)
        endpoint = TCP4ClientEndpoint(reactor, self.host, self.port,
                                      timeout=30)
        d = endpoint.connect(VNCClientAuthenticatorFactory(self.password))
        d.addCallback(prepare_proxy, server)
        @d.addErrback
        def cancel_proxy(failure):
            log.err()
            log.msg("Couldn't connect to server, cancelling proxy")
            server.transport.loseConnection()
        return server
class ControlProtocol(LineReceiver):
    def lineReceived(self, line):
        log.msg("Received line %s" % line)
        try:
            d = loads(line)
            host = d["daddr"]
            dport = d["dport"]
            password = d["password"]
            sport = d.get("sport")
            ws = d.get("ws", False)
            tls = d.get("tls", False)
            client_opts = d.get("client", {})
            sport = self.factory.allocate_port(sport)
            factory = VNCProxy(host, dport, password, client_opts)
            if ws:
                factory = WebSocketFactory(factory)
            if tls:
                context = DefaultOpenSSLContextFactory("keys/vncap.key",
                                                       "keys/vncap.crt")
                listening = reactor.listenSSL(sport, factory, context)
            else:
                listening = reactor.listenTCP(sport, factory)
            def timeout():
                log.msg("Timed out connection on port %d" % sport)
                listening.stopListening()
                self.factory.free_port(sport)
            reactor.callLater(30, timeout)
            log.msg("New forwarder (%d->%s:%d)" % (sport, host, dport))
            self.sendLine("%d" % sport)
        except (KeyError, ValueError):
            log.msg("Couldn't handle line %s" % line)
            self.sendLine("FAILED")
        except CannotListenError:
            log.msg("Couldn't bind port %d" % sport)
            self.sendLine("FAILED")
        self.transport.loseConnection()
    protocol = ControlProtocol

