        if document:
            return mark_safe(
                '<a href="%s">%s <span class="meta">(%s, %s)</span></a>'
                % (
                    document.url,
                    document.title,
                    document.file_extension.upper(),
                    filesizeformat(document.file.size),
                )
            )
        return self.model_admin.get_empty_value_display(field_name)
    def get_dict_for_field(self, field_name):
