                ).strip(),
                title="SQL Interrupted",
                status=400,
                message_is_html=True,
            )
        except sqlite3.DatabaseError as ex:
            query_error = str(ex)
            results = None
            rows = []
            columns = []
        except (sqlite3.OperationalError, InvalidSql) as ex:
