                self._preload()
                config = self._reload()
                self._ip_addr = config.get('ip_addr')
                self._sendmail = config.get('sendmail')
                self._save_thread = config.get('save_thread')
                self._user_agents_list = config.get('user_agents_list')
                self._storage_engines = config.get('storage_engines')
                self._save_dir = config.get('save_dir')
                self._archive_dir = config.get('archive_dir')
                self._compress = config.get('compress')
                self._proxies_list = config.get('proxies_list')
                self._re_module = config.get('re_module')
                self._patterns = config.get('patterns')
                self._sites = config.get('sites')
                self._threads = config.get('threads')
                self._pidfile = config.get('pidfile')
                self._max_throttling = 0
                for site in self._sites:
                    if self._max_throttling < site.throttling:
                        self._max_throttling = site.throttling
        except PystemonConfigException:
            raise
        except Exception as e:
            raise PystemonConfigException('Unable to parse configuration: {}'.format(e))
        logger.debug("configuration loaded")
        return True
    def _preload(self):
        if self._yamlconfig is None:
            logger.debug("pre-loading config file '{}'".format(self._configfile))
            self._yamlconfig = self._load_yamlconfig(self._configfile)
            try:
                self._pidfile = self._yamlconfig['pid']['filename']
            except KeyError:
                pass
    def _reload(self):
        logger.debug("parsing yaml configuration from file '{}'".format(self._configfile))
        config = {}
        yamlconfig = self._yamlconfig
        try:
            if yamlconfig['proxy']['random']:
                config['proxies_list'] = ProxyList(yamlconfig['proxy']['file'])
        except KeyError:
            pass
        config['save_thread'] = yamlconfig.get('save-thread', False)
        uaconfig = yamlconfig.get('user-agent', {})
        if uaconfig.get('random', False):
            try:
                config['user_agents_list'] = self._load_user_agents_from_file(yamlconfig['user-agent']['file'])
            except KeyError:
                raise PystemonConfigException('random user-agent requested but no file provided')
        try:
            ip_addr = yamlconfig['network']['ip']
        except KeyError:
            logger.debug("Using default IP address")
            pass
        config['sendmail'] = self._load_email(yamlconfig)
        res = self._load_storage_engines(yamlconfig)
        config['storage_engines'] = res['engines']
        config['save_dir'] = res['save_dir']
        config['archive_dir'] = res['archive_dir']
        config['compress'] = res['compress']
        config['re_module'] = self._load_regex_engine(yamlconfig)
        config['patterns'] = self._compile_regex(yamlconfig, config['re_module'])
        try:
            config['threads'] = int(yamlconfig.get('threads', 1))
            if config['threads'] < 1:
                raise Exception("minimum acceptable value is 1")
        except Exception as e:
            logger.error("invalid threads value specified: {0}".format(e))
            config['threads'] = 1
            pass
        config['sites'] = self._load_sites(yamlconfig)
        if not self.debug and 'logging-level' in yamlconfig:
            if yamlconfig['logging-level'] in ['NOTSET', 'DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL']:
                logger.setLevel(logging.getLevelName(yamlconfig['logging-level']))
            else:
                logger.error("logging level \"%s\" is invalid" % (yamlconfig['logging-level']))
        logger.debug("yaml configuration parsed")
        return config
    def _recent_pyyaml(self):
        res = False
        try:
            version = yaml.__version__.split('.')
            if int(version[0]) >= 5:
                if int(version[1]) >= 1:
                    res = True
        except Exception as e:
            logger.debug("unable to parse PyYaml version: {}".format(e))
        return res
    def _load_yamlconfig(self, configfile):
        yamlconfig = None
        try:
            if self._recent_pyyaml():
                yamlconfig = yaml.load(open(configfile), Loader=yaml.FullLoader)
            else:
                yamlconfig = yaml.load(open(configfile))
        except yaml.YAMLError as exc:
            logger.error("Error in configuration file {0}:".format(configfile))
            if hasattr(exc, 'problem_mark'):
                mark = exc.problem_mark
                raise PystemonConfigException("error position: (%s:%s)" % (mark.line + 1, mark.column + 1))
        for includes in yamlconfig.get("includes", []):
            try:
                logger.debug("loading include '{0}'".format(includes))
                yamlconfig.update(yaml.load(open(includes)))
            except Exception as e:
                raise PystemonConfigException("failed to load '{0}': {1}".format(includes, e))
        return yamlconfig
    def _load_user_agents_from_file(self, filename):
        user_agents_list = []
        logger.debug('Loading user-agent from file "{file}" ...'.format(file=filename))
        with open(filename) as f:
            for line in f:
                line = line.strip()
                if line:
                    user_agents_list.append(line)
        if not len(user_agents_list) > 0:
            raise PystemonConfigException("found zero valid UserAgents")
        logger.debug("Found {count} UserAgents in file '{file}'".format(file=filename, count=len(user_agents_list)))
        return user_agents_list
    def _load_email(self, yamlconfig):
        sendmail = None
        email=yamlconfig.get('email', {})
        if email.get('alert'):
            logger.debug('loading email configuration')
            sendmail = PystemonSendmail(email['from'], email['to'], email['subject'],
                    server=email.get('server', '127.0.0.1'),
                    port=email.get('port', 25),
                    tls=email.get('tls', False),
                    username=email.get('username'),
                    password=email.get('password'),
                    size_limit=email.get('size-limit', 1024*1024))
            logger.debug("alert emails will be sent to '{0}' from '{1}' via '{2}'".format(sendmail.mailto, sendmail.mailfrom, sendmail.server))
        return sendmail
    def _load_storage_engines(self, yamlconfig):
        storage_engines = []
        storage_yamlconfig = yamlconfig.get('storage', {})
        save_dir = None
        archive_dir = None
        storage_file = None
        compress = False
        try:
            storage_file = PastieStorage.load_storage('archive', **storage_yamlconfig.pop('archive'))
            if storage_file is not None:
                save_dir = storage_file.save_dir
                archive_dir = storage_file.archive_dir
                compress = storage_file.compress
                storage_engines.append(storage_file)
        except KeyError as e:
            raise PystemonConfigException('archive was not found under storage, old pystemon.yaml config?')
        for storage in storage_yamlconfig.keys():
            engine = PastieStorage.load_storage(storage, save_dir=save_dir, archive_dir=archive_dir,
                    **storage_yamlconfig[storage])
            if engine is not None:
                storage_engines.append(engine)
        return {'save_dir': save_dir, 'archive_dir': archive_dir, 'compress': compress, 'engines': storage_engines}
    def _load_regex_engine(self, yamlconfig):
        engine = yamlconfig.get('engine', 're')
        re_module = None
        if not engine in ['re', 'regex']:
            raise PystemonConfigException("only 're' or 'regex' supported, not '{0}'".format(engine))
        try:
            logger.debug("Loading regular expression engine '{0}'".format(engine))
            re_module=importlib.import_module(engine)
            if engine == 'regex':
                logger.debug("Setting regex DEFAULT_VERSION to VERSION1")
                re_module.DEFAULT_VERSION = re.VERSION1
        except ImportError as e:
            raise PystemonConfigException("unable to import module '{0}'".format(engine))
        return re_module
    def _compile_regex(self, yamlconfig, re_module):
        patterns = []
        strict = yamlconfig.get('strict_regex', False)
        regexes = yamlconfig['search']
        logger.debug("compiling {} regexes ...".format(len(regexes)))
        for regex in regexes:
            try:
                search = regex['search']
                ps = PastieSearch(re_module, regex)
                patterns.append(ps)
            except KeyError:
                if strict:
                    raise PystemonConfigException("Missing search pattern")
                else:
                    logger.error("Error: skipping empty search pattern entry")
            except Exception as e:
                if strict:
                    raise PystemonConfigException("Unable to parse regex '%s': %s" % (search, e))
                else:
                    logger.error("Error: Unable to parse regex '%s': %s" % (search, e))
        logger.debug("successfully compiled {0}/{1} regexes".format(len(patterns), len(regexes)))
        return patterns
    def _load_sites(self, yamlconfig):
        sites_enabled = []
        count_enabled = 0
        sites = yamlconfig['site']
        logger.debug("loading {} sites ...".format(len(sites)))
        for site in sites:
            if yamlconfig['site'][site].get('enable'):
                logger.info("Site: {} is enabled, adding to pool...".format(site))
                new_site = None
                try:
                    count_enabled = count_enabled + 1
                    new_site = SiteConfig(site, yamlconfig['site'][site])
                    if new_site in self._sites:
                        i = self._sites.index(new_site)
                        logger.debug("found {} in running configuration".format(repr(new_site)))
                        current_site = self._sites[i]
                        logger.debug("matching running site: {}".format(current_site))
                        q = current_site.queue
                        logger.debug("running queue size: {}".format(q.qsize()))
                        new_site.queue = q
                    sites_enabled.append(new_site)
                except Exception as e:
                    logger.error("Unable to add site '{0}': {1}".format(site, e))
            elif yamlconfig['site'][site].get('enable') is False:
                logger.info("Site: {} is disabled.".format(site))
            else:
                logger.warning("Site: {} is not enabled or disabled in config file. We just assume it disabled.".format(site))
        logger.debug("successfully loaded {0}/{1} enabled site(s)".format(len(sites_enabled), count_enabled))
        return sites_enabled
class PastieSearch():
    def __init__(self, engine, regex):
        if 'regex-flags' in regex:
            self.regex_flags = regex['regex-flags']
            self.flags = eval(self.regex_flags)
        else:
            self.regex_flags = None
            self.flags = engine.IGNORECASE
        self.search = regex['search']
        try:
            self.re_search = engine.compile(self.search.encode(), self.flags)
        except Exception as e:
            raise ValueError("invalid search regex: %s" % e)
        self.exclude = regex.get('exclude')
        if self.exclude is not None:
            try:
                self.re_exclude = engine.compile(self.exclude.encode(), self.flags)
            except Exception as e:
                raise ValueError("invalid exclude regex: %s" % e)
        self.description = regex.get('description')
        if 'count' in regex:
            self.count = int(regex['count'])
        else:
            self.count = -1
        self.to = regex.get('to')
        if self.to is not None:
            self.ato = self.to.split(",")
        else:
            self.ato = []
        self.extra = {}
        for (k, v) in regex.items():
            if k in ['search', 'description', 'exclude', 'count', 'regex-flags', 'to']:
                continue
            self.extra[k] = v
        self.h = None
        logger.debug("[{0}]: compiled into: {1}".format(self.search, self.re_search))
    def __str__(self):
        return self.to_text()
    def __repr__(self):
        return self.to_regex()
    def match(self, string):
        m = self.re_search.findall(string)
        if not m:
            return False
        if (self.count > 0) and (len(m) < self.count):
            return False
        if self.exclude is not None:
            if self.re_exclude.search(string):
                return False
        return True
    def to_text(self):
        if self.description is None:
            return self.search
        return self.description
    def to_regex(self):
        return self.search
    def to_dict(self):
        if self.h is None:
            self.h = {'search': self.search}
            if self.description is not None:
                self.h['description'] = self.description
            if self.exclude is not None:
                self.h['exclude'] = self.exclude
            if self.count >= 0:
                self.h['count'] = self.count
            if self.to is not None:
                self.h['to'] = self.to
            if self.regex_flags is not None:
                self.h['regex-flags'] = self.regex_flags
            for (k, v) in self.extra.items():
                self.h[k] = v
        return self.h
class ThreadProxyList(threading.Thread):
    def __init__(self, proxies_list, wait=1):
        threading.Thread.__init__(self)
        self.list = proxies_list
        self.last_mtime = proxies_list.last_mtime
        self.wait = wait
        self.condition = threading.Condition()
        self.kill_received = False
    def __repr__(self):
        return 'ThreadProxyList[{}]'.format(self.list.filename)
    def stop(self):
        with self.condition:
            logger.info('ThreadProxyList exiting')
            self.kill_received = True
            self.condition.notify_all()
    def reset(self, wait=1):
        with self.condition:
            self.last_mtime = 0
            self.filename = filename
            self.wait = wait
    def run(self):
        logger.info('ThreadProxyList started')
        try:
            with self.condition:
                while not self.kill_received:
                    mtime = os.stat(self.list.filename).st_mtime
                    if mtime != self.last_mtime:
                        logger.debug('Proxy configuration file changed. Reloading proxy list.')
                        self.list.load_proxies_from_file()
                        self.last_mtime = mtime
                    self.condition.wait(1)
        except Exception as e:
            logger.error('ThreadProxyList crashed: {0}'.format(e))
        logger.info('ThreadProxyList exited')
class ProxyList():
    def __init__(self, filename):
        self.proxies_failed = []
        self.proxies_list = []
        self.proxies_lock = threading.Lock()
        self.thread_proxy_list = None
        self.filename = filename
        self.last_mtime = 0
        self.load_proxies_from_file()
    def monitor(self, wait=1):
        if self.thread_proxy_list:
            self.thread_proxy_list.reset(self, wait)
        else:
            t = ThreadProxyList(self, wait)
            t.setDaemon(True)
            t.start()
            self.thread_proxy_list = t
        return self.thread_proxy_list
    def load_proxies_from_file(self):
        try:
            filename = self.filename
            logger.debug('Loading proxy configuration from file "{file}" ...'.format(file=filename))
            proxies_list = []
            with self.proxies_lock, open(filename) as f:
                self.last_mtime = os.fstat(f.fileno()).st_mtime
                for line in f:
                    line = line.strip()
                    if line:
                        proxies_list.append(line)
                self.proxies_failed = []
                self.proxies_list = proxies_list
            logger.debug('Found {count} proxies in file "{file}"'.format(file=filename, count=len(proxies_list)))
        except Exception as e:
            logger.error('Configuration problem: error reading proxyfile "{file}": {e}'.format(file=filename, e=e))
    def get_random_proxy(self):
        proxy = None
        with self.proxies_lock:
            if self.proxies_list:
                proxy = random.choice(tuple(self.proxies_list))
        return proxy
    def failed_proxy(self,proxy):
        with self.proxies_lock:
            if len(self.proxies_list) == 1:
                logger.info("Failing proxy {} not removed as it's the only proxy left.".format(proxy))
            else:
                self.proxies_failed.append(proxy)
                if self.proxies_failed.count(proxy) >= 2 and proxy in self.proxies_list:
                    logger.info("Removing proxy {0} from proxy list because of to many errors errors.".format(proxy))
                    try:
                        self.proxies_list.remove(proxy)
                    except ValueError:
                        pass
                    logger.info("Proxies left: {0}".format(len(self.proxies_list)))
class PystemonConfigException(PystemonException):
def load_config(config):
    logger.debug("About to load configuration")
    config.reload()
    threads=[]
    sites_loaded=0
    if config.proxies_list is not None:
        threads.append(config.proxies_list.monitor())
    storage = StorageDispatcher()
    if config.storage_engines:
        if config.save_thread:
            logger.info("Pasties will be saved asynchronously")
        else:
            logger.info("Pasties will be saved synchronously")
        for db in config.storage_engines:
            if config.save_thread:
                t = StorageThread(db)
                threads.append(t)
                storage.add_storage(t)
                t.setDaemon(True)
            else:
                s = StorageSync(db)
                storage.add_storage(s)
    else:
        logger.info("Pasties will not be saved")
    '''
     for each site enabled:
     - get the configuration
     - if successfull, create a queue
     - create a thread to refresh the list of pasties to download (consumer)
     - create a thread to download the pasties (consumer)
     - if needed, create a thread to throttle all the other threads (producer)
    '''
    for site in config.sites:
        try:
            throttler = None
            if site.throttling > 0:
                logger.debug("enabling throttling on site {site}".format(site=site.name))
                throttler = ThreadThrottler(site.name, site.throttling)
                threads.append(throttler)
                throttler.setDaemon(True)
            for i in range(config.threads):
                name = "[ThreadPasties][{}][{}]".format(site.name, i+1)
                user_agent = PystemonUA(name, config.proxies_list,
                        user_agents_list = config.user_agents_list,
                        throttler=throttler, ip_addr=config.ip_addr)
                t = ThreadPasties(user_agent, queue_name=site.name, queue=site.queue)
                threads.append(t)
                t.setDaemon(True)
            name = "[PastieSite][{}]".format(site.name)
            site_ua=PystemonUA(name, config.proxies_list,
                user_agents_list = config.user_agents_list,
                throttler = throttler, ip_addr = config.ip_addr)
            t = PastieSite(site.name, site.download_url, site.archive_url, site.archive_regex,
                    site_public_url = site.public_url,
                    site_metadata_url = site.metadata_url,
                    site_update_min = site.update_min,
                    site_update_max = site.update_max,
                    site_pastie_classname = site.pastie_classname,
                    site_save_dir = config.save_dir,
                    site_archive_dir = config.archive_dir,
                    archive_compress = config.compress,
                    site_ua=site_ua,
                    site_queue=site.queue,
                    patterns=config.patterns,
                    sendmail=config.sendmail,
                    re=config.re_module)
            t.set_storage(storage)
            threads.append(t)
            t.setDaemon(True)
            sites_loaded = sites_loaded + 1
        except Exception as e:
            logger.error('Unable to initialize pastie site {0}: {1}'.format(site.name, e))
    logger.debug("Finished loading configuration, {} thread(s) to start".format(len(threads)))
    if not sites_loaded > 0:
        raise PystemonConfigEmpty("Resulting configuration ends up monitoring no site")
    return threads
def start_threads(threads):
    count = len(threads)
    logger.debug("starting {0} thread(s) ...".format(count))
    for t in threads:
        t.start()
def stop_threads(threads):
    count = len(threads)
    if not count > 0:
        return
    logger.debug("stopping {0} thread(s) ...".format(count))
    for t in threads:
        t.stop()
def join_threads(threads, timeout=None, stop_requested=False):
    count = len(threads)
    if not count > 0:
        return True
    joined = 0
    terminated = 0
    if stop_requested:
        logger.debug("joining {} threads ...".format(count))
    else:
        logger.debug("checking on {} threads ...".format(count))
    if timeout is not None:
        logger.debug("will wait maximum {}s for each thread".format(timeout))
    for t in threads:
        try:
            t.join(timeout)
            joined = joined + 1
            if not t.is_alive():
                terminated = terminated + 1
        except PystemonException:
            raise
        except KeyboardInterrupt:
            raise
        except Exception as e:
            logger.error("failed to join thread '{0}': {1}".format(t, e))
            pass
    if stop_requested:
        logger.debug("{0}/{1} thread(s) terminated".format(terminated, count))
    else:
        logger.debug("{0}/{1} thread(s) still alive".format(count-terminated, count))
    return terminated == count
def main(config):
    res = 0
    reload_requested = True
    stop_requested = False
    threads = []
    def request_stop(signal, frame):
        raise PystemonStopRequested("stop requested")
    signal.signal(signal.SIGTERM, request_stop)
    def request_reload(signal, frame):
        raise PystemonReloadRequested("reload requested")
    signal.signal(signal.SIGHUP, request_reload)
    def request_queue_stats(signal, frame):
        raise PystemonQueueStatRequested("queues stats requested")
    signal.signal(signal.SIGUSR1, request_queue_stats)
    while True:
        try:
            if not len(threads) > 0:
                raise PystemonReloadRequested("Starting up ...")
            join_threads(threads, timeout=1)
        except PystemonReloadRequested as e:
            logger.info("Pystemon[{}]: {}".format(os.getpid(), e))
            try:
                new_threads = load_config(config)
                stop_threads(threads)
                join_threads(threads, stop_requested=True)
                threads = new_threads
                start_threads(threads)
            except PystemonConfigException as e:
                if not len(threads) > 0:
                    raise
                logger.error('Pystemon[{}]: {}'.format(os.getpid(), e))
                logger.info('Pystemon[{}]: continuing with previous configuration'.format(os.getpid()))
                pass
        except (PystemonStopRequested, KeyboardInterrupt) as e:
            if isinstance(e, PystemonException):
                logger.info("Pystemon[{}]: {}".format(os.getpid(), e))
            else:
                print('')
                print("Ctrl-c received! Sending kill to threads...")
            stop_threads(threads)
            join_threads(threads, timeout=max(1, config.max_throttling / 1000), stop_requested=stop_threads)
            break
        except PystemonQueueStatRequested as e:
            logger.debug("{}".format(e))
            for site in config.sites:
                try:
                    logger.info("{}: queue size={}".format(repr(site), site.queue.qsize()))
                except:
                    pass
        except PystemonConfigException as e:
            logger.error('Pystemon[{}]: {}'.format(os.getpid(), e))
            res = 2
            break
        except Exception as e:
            logger.error('Pystemon crashed: {}'.format(e))
            res = 1
            break
    logger.info('exiting')
    exit(res)
def main_as_daemon(config):
    try:
        pid = os.fork()
        if pid > 0:
            pid_file = config.pidfile
            if pid_file is not None:
                pid_file = open(pid_file, 'w')
                pid_file.write(str(pid))
                pid_file.close()
            print('pystemon started as daemon')
            print('PID: %d' % pid)
            os._exit(0)
    except OSError as error:
        logger.error('Unable to fork, can\'t run as daemon. Error: {id} {error}'.format(id=error.errno, error=error.strerror))
        os._exit(1)
    main(config)
if __name__ == "__main__":
