            pid = f.read()
            f.close()
            os.remove(pidfile)
            print("Sending signal to pid: {}".format(pid))
            os.kill(int(pid), 2)
            os._exit(0)
        else:
            print("PID file not found. Nothing to do.")
            os._exit(0)
    if options.daemon:
        main_as_daemon(config)
    else:
        main(config)
